package ledger

// Entry is a single row of the ledger: a date, a description and a change
// expressed in cents (negative for a debit, positive for a credit).
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

// FormatLedger returns a formatted, human-readable ledger for the given
// currency and locale. The input entries slice is never mutated.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	if err := validateCurrency(currency); err != nil {
		return "", err
	}
	if err := validateLocale(locale); err != nil {
		return "", err
	}

	// Sort a copy so the caller's slice is left untouched.
	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sortEntries(sorted)

	var b strings.Builder
	b.WriteString(header(locale))
	for _, e := range sorted {
		line, err := formatEntry(currency, locale, e)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

// validateCurrency ensures the currency is one of the supported codes.
func validateCurrency(currency string) error {
	if currency != "USD" && currency != "EUR" {
		return errors.New("invalid currency")
	}
	return nil
}

// validateLocale ensures the locale is one of the supported locales.
func validateLocale(locale string) error {
	if locale != "en-US" && locale != "nl-NL" {
		return errors.New("invalid locale")
	}
	return nil
}

// sortEntries orders entries by date, then description, then change (all
// ascending), which is the presentation order required by the ledger.
func sortEntries(entries []Entry) {
	sort.SliceStable(entries, func(i, j int) bool {
		a, b := entries[i], entries[j]
		if a.Date != b.Date {
			return a.Date < b.Date
		}
		if a.Description != b.Description {
			return a.Description < b.Description
		}
		return a.Change < b.Change
	})
}

// header renders the column titles. The date and description columns are
// left aligned; the change column is left as-is (no trailing padding).
func header(locale string) string {
	dateCol, descCol, changeCol := "Date", "Description", "Change"
	if locale == "nl-NL" {
		dateCol, descCol, changeCol = "Datum", "Omschrijving", "Verandering"
	}
	return dateCol + strings.Repeat(" ", 10-len(dateCol)) + " | " +
		descCol + strings.Repeat(" ", 25-len(descCol)) + " | " +
		changeCol + "\n"
}

// formatEntry renders a single ledger row.
func formatEntry(currency, locale string, e Entry) (string, error) {
	date, err := formatDate(locale, e.Date)
	if err != nil {
		return "", err
	}
	desc := formatDescription(e.Description)
	change, err := formatChange(currency, locale, e.Change)
	if err != nil {
		return "", err
	}
	// The date is always 10 bytes and the description always 25 bytes, so
	// only the change column needs right alignment (padded by rune count so
	// that multi-byte symbols such as "€" align correctly).
	return date + " | " + desc + " | " + padRight(change, 13) + "\n", nil
}

// formatDate validates and reformats a "YYYY-MM-DD" date for the locale:
// "MM/DD/YYYY" for en-US and "DD-MM-YYYY" for nl-NL.
func formatDate(locale, date string) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", errors.New("invalid date")
	}
	year, month, day := date[0:4], date[5:7], date[8:10]
	if locale == "nl-NL" {
		return day + "-" + month + "-" + year, nil
	}
	return month + "/" + day + "/" + year, nil
}

// formatDescription pads the description to 25 bytes, or truncates overly
// long ones to 22 bytes followed by an ellipsis.
func formatDescription(desc string) string {
	if len(desc) > 25 {
		return desc[:22] + "..."
	}
	return desc + strings.Repeat(" ", 25-len(desc))
}

// formatChange renders the change amount for the given locale and currency.
func formatChange(currency, locale string, change int) (string, error) {
	symbol, err := currencySymbol(currency)
	if err != nil {
		return "", err
	}
	negative := change < 0
	if negative {
		change = -change
	}
	dollars := change / 100
	cents := change % 100

	if locale == "nl-NL" {
		// e.g. "$ 1.234,56 " (credit) or "$ 123,45-" (debit)
		suffix := " "
		if negative {
			suffix = "-"
		}
		return symbol + " " + groupDollars(dollars, ".") + "," + twoDigit(cents) + suffix, nil
	}
	// en-US: e.g. "$10.00 " (credit) or "($10.00)" (debit)
	if negative {
		return "(" + symbol + groupDollars(dollars, ",") + "." + twoDigit(cents) + ")", nil
	}
	return symbol + groupDollars(dollars, ",") + "." + twoDigit(cents) + " ", nil
}

// currencySymbol maps a supported currency code to its symbol.
func currencySymbol(currency string) (string, error) {
	switch currency {
	case "USD":
		return "$", nil
	case "EUR":
		return "€", nil
	default:
		return "", errors.New("invalid currency")
	}
}

// groupDollars inserts sep between every three digits of the whole-dollar
// part, counting from the right (e.g. 1234 -> "1,234" or "1.234").
func groupDollars(dollars int, sep string) string {
	s := strconv.Itoa(dollars)
	if len(s) <= 3 {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteString(sep)
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

// twoDigit renders a 0-99 value as exactly two digits.
func twoDigit(n int) string {
	return string('0'+n/10) + string('0'+n%10)
}

// runeLen returns the number of runes in s.
func runeLen(s string) int {
	n := 0
	for range s {
		n++
	}
	return n
}

// padRight right-aligns s within width columns, padding with spaces. Width is
// measured in runes so multi-byte symbols align correctly; a string wider than
// width is returned unchanged rather than truncating.
func padRight(s string, width int) string {
	if n := runeLen(s); n < width {
		return strings.Repeat(" ", width-n) + s
	}
	return s
}

